import unittest
from candidate import factorize

class TestFactorizeFunction(unittest.TestCase):
    def test_factorize_small_prime_number(self):
        self.assertEqual(factorize(7), [7])

    def test_factorize_small_composite_number(self):
        self.assertEqual(factorize(8), [2, 2, 2])

    def test_factorize_medium_composite_number(self):
        self.assertEqual(factorize(70), [2, 5, 7])

    def test_factorize_power_of_prime_number(self):
        self.assertEqual(factorize(25), [5, 5])

    def test_factorize_large_prime_number(self):
        self.assertEqual(factorize(104729), [104729])

    def test_factorize_edge_case_one(self):
        self.assertEqual(factorize(1), [])

    def test_factorize_edge_case_zero(self):
        with self.assertRaises(ValueError):
            factorize(0)

    def test_factorize_edge_case_negative(self):
        with self.assertRaises(ValueError):
            factorize(-10)

    def test_factorize_input_type_error(self):
        with self.assertRaises(TypeError):
            factorize("10")

    def test_factorize_input_none(self):
        with self.assertRaises(TypeError):
            factorize(None)

if __name__ == '__main__':
    unittest.main()
